class AuditModelAllocationActivity:ComponentActivity(){override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);enableEdgeToEdge();val vm=ViewModelProvider(this)[AuditModelAllocationViewModel::class.java];setContent{MaterialTheme(colorScheme=if(androidx.compose.foundation.isSystemInDarkTheme())darkColorScheme()else lightColorScheme()){Screen(vm){finish()}}}}}
@Composable private fun Screen(vm:AuditModelAllocationViewModel,onBack:()->Unit){val models by vm.models.collectAsStateWithLifecycle();val reviewers by vm.reviewers.collectAsStateWithLifecycle();val chairman by vm.chairman.collectAsStateWithLifecycle();val loading by vm.loading.collectAsStateWithLifecycle();val message by vm.message.collectAsStateWithLifecycle();val readiness by vm.readiness.collectAsStateWithLifecycle();val health by vm.health.collectAsStateWithLifecycle();var picker by remember{mutableStateOf<Int?>(null)};var finalPick by remember{mutableStateOf(false)};if(picker!=null||finalPick)Picker(if(finalPick)"Choose Final Reviewer" else "Choose Reviewer ${(picker?:0)+1}",models,if(finalPick)chairman else reviewers.getOrNull(picker?:-1).orEmpty(),vm,{id->if(finalPick)vm.setChairman(id)else picker?.let{vm.setReviewer(it,id)};picker=null;finalPick=false},{picker=null;finalPick=false});Scaffold(topBar={TopAppBar(title={Column{Text("Audit review team",fontWeight=FontWeight.Bold);Text("Live qualification before use",style=MaterialTheme.typography.labelSmall)}},navigationIcon={IconButton(onClick=onBack){Icon(Icons.Default.ArrowBack,"Back")}},actions={IconButton(onClick={vm.loadModels();vm.loadHealth()}){Icon(Icons.Default.Refresh,"Refresh")}})}){pad->LazyColumn(Modifier.fillMaxSize().padding(pad),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{ElevatedCard{Column(Modifier.padding(14.dp),verticalArrangement=Arrangement.spacedBy(7.dp)){Text("Model readiness",fontWeight=FontWeight.Bold);Text("Every model must pass a live repository-audit probe before it is considered ready. Paid OpenRouter selections are rejected when the current key cannot use them; qualified zero-cost alternatives are preferred.",style=MaterialTheme.typography.bodySmall);Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedButton(onClick=vm::autoSelectRecommended,enabled=models.size>=2&&!loading){Text("Auto-select qualified")};OutlinedButton(onClick=vm::qualifySelectedTeam,enabled=!loading){Text("Test team")}}}}};if(loading)item{LinearProgressIndicator(Modifier.fillMaxWidth())};message?.let{item{AssistChip(onClick=vm::clearMessage,label={Text(it,maxLines=3,overflow=TextOverflow.Ellipsis)})}};item{Text("Independent Reviewers",style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.Bold)};items(reviewers.indices.toList(),key={it}){i->val id=reviewers[i];ElevatedCard{Column(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(5.dp)){Text("Reviewer ${i+1}",fontWeight=FontWeight.SemiBold);Text(vm.modelLabel(id));Text(vm.healthLabel(id),style=MaterialTheme.typography.labelSmall,color=if(vm.auditReady(id))MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant);Row{Button(onClick={picker=i}){Text(if(id.isBlank())"Choose" else "Change")};if(reviewers.size>2||id.isNotBlank())TextButton(onClick={vm.removeReviewer(i)}){Text("Remove")}}}}};item{OutlinedButton(onClick=vm::addReviewer,enabled=reviewers.size<8,modifier=Modifier.fillMaxWidth()){Text("Add Reviewer")}};item{ElevatedCard(colors=CardDefaults.elevatedCardColors(containerColor=MaterialTheme.colorScheme.surfaceVariant)){Column(Modifier.padding(14.dp)){Text("Final Reviewer",fontWeight=FontWeight.Bold);Text(vm.modelLabel(chairman));Text(vm.healthLabel(chairman),style=MaterialTheme.typography.labelSmall,color=if(vm.auditReady(chairman))MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant);Button(onClick={finalPick=true}){Text(if(chairman.isBlank())"Choose Final Reviewer" else "Change")}}}};item{val ok=vm.valid();Card(colors=CardDefaults.cardColors(containerColor=if(ok)MaterialTheme.colorScheme.secondaryContainer else MaterialTheme.colorScheme.errorContainer)){Text(if(ok)"Team ready: all assigned models are audit-qualified" else "Team is not audit-ready yet",Modifier.padding(12.dp))}}}}}
@Composable private fun Picker(title:String,models:List<OpenRouterModel>,current:String,vm:AuditModelAllocationViewModel,onSelect:(String)->Unit,onDismiss:()->Unit){var q by remember{mutableStateOf("")};var qualified by remember{mutableStateOf(false)};var free by remember{mutableStateOf(false)};val filtered=models.filter{m->(!qualified||vm.auditReady(m.id))&&(!free||m.isFree)&&(q.isBlank()||m.name.contains(q,true)||m.id.contains(q,true)||m.provider.contains(q,true))};AlertDialog(onDismissRequest=onDismiss,title={Text(title)},confirmButton={TextButton(onClick=onDismiss){Text("Cancel")}},text={Column(Modifier.fillMaxWidth().heightIn(max=620.dp)){OutlinedTextField(q,{q=it},Modifier.fillMaxWidth(),label={Text("Search models")});Row{FilterChip(qualified,{qualified=!qualified},label={Text("Audit-qualified")});Spacer(Modifier.width(6.dp));FilterChip(free,{free=!free},label={Text("Free")})};LazyColumn(Modifier.weight(1f)){items(filtered,key={it.id}){m->ElevatedCard(onClick={onSelect(m.id)},modifier=Modifier.fillMaxWidth().padding(vertical=3.dp)){Column(Modifier.padding(10.dp)){Text(m.name,fontWeight=if(m.id==current)FontWeight.Bold else FontWeight.SemiBold);Text("${m.source.displayName} · ${m.provider}${if(m.isFree)" · Free" else " · Paid/usage-based"}",style=MaterialTheme.typography.labelSmall);Text(vm.healthLabel(m.id),style=MaterialTheme.typography.labelSmall);Text(m.id,maxLines=1,overflow=TextOverflow.Ellipsis,style=MaterialTheme.typography.labelSmall)}}}}}})}
